struct sub { int topic; void (*fn)(void *, const struct event *); void *ud; };
static struct sub subs[MAX_SUBS];
static size_t n_subs;

void publish(const struct event *e) {
    for (size_t i = 0; i < n_subs; i++)
        if (subs[i].topic == e->topic) subs[i].fn(subs[i].ud, e);
}

